<script lang="ts">
  import { onMount } from 'svelte';
  import type { ApiClient } from '../api/client';
  import { createCameraStore, type CamerasState } from '../stores/cameras';
  import HlsPlayer from './HlsPlayer.svelte';

  let { client }: { client: ApiClient } = $props();
  const createStore = () => createCameraStore(client);
  const store = createStore();
  let state: CamerasState = $state(store.state);
  const selected = $derived(state.items.find((item) => item.camera_id === state.selected) ?? null);
  const confidence = (value: number) => `${Math.round(value * 100)}% confident`;
  const health = (value: string) => value[0]?.toUpperCase() + value.slice(1);
  const streams = $derived(selected?.streams ?? []);
  onMount(() => { const unsubscribe = store.subscribe((next) => state = next); void store.load(); return () => { unsubscribe(); void store.dispose(); }; });
</script>

<section class="cameras-view" aria-labelledby="cameras-heading">
  <div class="view-heading camera-heading"><div><p class="kicker">CAMERAS / PRIVATE VIEW</p><h1 id="cameras-heading">Watch the threshold.</h1><p class="muted">See only verified camera details. Video stays inside your local service.</p></div><span class="camera-beacon" aria-hidden="true"><i></i> LIVE SIGNAL</span></div>
  {#if state.loading}<div class="camera-state" role="status">Reading camera inventory…</div>{:else if state.error}<div class="camera-state error" role="alert">{state.error}</div>{:else if state.items.length === 0}<div class="empty-state"><span class="empty-icon" aria-hidden="true">□</span><div><strong>No verified cameras yet</strong><p class="muted">When a camera earns enough evidence, it will appear here.</p></div></div>{:else}
    <div class="camera-grid" aria-label="Verified cameras">{#each state.items as item}<button class:active={item.camera_id === state.selected} class="camera-card" type="button" aria-pressed={item.camera_id === state.selected} onclick={() => store.select(item.camera_id)}><span class="camera-eye" aria-hidden="true">◉</span><span><strong>{item.inventory?.manufacturer && item.inventory?.model ? `${item.inventory.manufacturer} ${item.inventory.model}` : 'Verified camera'}</strong><small>{item.classification.replaceAll('_', ' ')}</small></span><span class="camera-card-status {item.health}">{health(item.health)}</span><span class="camera-confidence">{confidence(item.confidence)}</span></button>{/each}</div>
    {#if selected}<article class="camera-console"><div class="camera-console-head"><div><p class="kicker">CAMERA STATUS</p><h2>{selected.inventory?.manufacturer && selected.inventory?.model ? `${selected.inventory.manufacturer} ${selected.inventory.model}` : 'Verified camera'}</h2></div><span class="health-chip {selected.health}"><i></i>{health(selected.health)}</span></div><div class="camera-stage">{#if state.session}<HlsPlayer playlistUrl={state.session.playlistUrl} authorize={client.authorizeCameraMediaXhr} />{:else if state.snapshotUrl}<img src={state.snapshotUrl} alt="Latest camera snapshot" />{:else}<div class="live-fallback"><span aria-hidden="true">◌</span><strong>{streams.length ? 'Live view is ready' : 'Live view needs a stream selected'}</strong><p>{streams.length ? 'Start a local live view when you are ready.' : 'Snapshot capture remains available while the collector shares no stream selection.'}</p></div>{/if}</div><div class="camera-actions"><button type="button" onclick={() => store.snapshot(selected.camera_id)}>Capture snapshot</button>{#if streams.length}<button type="button" onclick={() => store.startSession(selected.camera_id, streams[0].stream_id)}>Start live view</button>{/if}{#if state.session}<button class="quiet-action" type="button" onclick={() => store.closeSession()}>Close live view</button>{/if}</div>{#if state.session}<p class="live-session" aria-live="polite">Live session is active. Your browser will use the collector-generated playlist.</p>{/if}<dl class="camera-facts"><div><dt>Confidence</dt><dd>{confidence(selected.confidence)}</dd></div><div><dt>Inventory health</dt><dd>{selected.inventory ? health(selected.inventory.health) : 'Unavailable'}</dd></div><div><dt>Owner serial</dt><dd>{selected.inventory?.serial ?? 'Unavailable'}</dd></div><div><dt>Firmware</dt><dd>{selected.inventory?.firmware ?? 'Unavailable'}</dd></div></dl></article>{/if}
  {/if}
</section>

<style>
  .camera-heading{display:flex;justify-content:space-between;gap:18px}.camera-beacon,.health-chip,.camera-card-status,.camera-confidence{font:500 10px var(--font-mono);text-transform:uppercase;letter-spacing:.08em}.camera-beacon{align-self:flex-end;color:var(--ink-mute)}.camera-beacon i,.health-chip i{display:inline-block;width:8px;height:8px;margin-right:6px;border-radius:50%;background:var(--ember);box-shadow:var(--ember-glow);animation:beacon 2.4s ease-in-out infinite}.camera-state{margin-top:28px;padding:18px;border:1px dashed var(--line);border-radius:var(--radius-card);color:var(--ink-mute)}.camera-state.error{border-color:var(--alert);color:var(--alert-text)}.camera-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:var(--gap-card);margin:27px 0 14px}.camera-card{min-width:0;display:grid;grid-template-columns:26px minmax(0,1fr) auto;gap:9px;align-items:center;padding:15px;border:1px solid var(--line);border-radius:var(--radius-card);background:var(--surface);color:var(--ink);text-align:left;cursor:pointer}.camera-card.active{border-color:var(--ember)}.camera-card strong,.camera-card small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.camera-card small{margin-top:4px;color:var(--ink-mute)}.camera-eye{color:var(--ink-mute);font-size:20px}.camera-card.active .camera-eye{color:var(--ember)}.camera-card-status{color:var(--sage-text)}.camera-card-status.degraded{color:var(--ink)}.camera-card-status.unknown{color:var(--ink-mute)}.camera-confidence{grid-column:2/-1;color:var(--ink-mute)}.camera-console{padding:var(--pad-card);border:1px solid var(--line);border-radius:var(--radius-card);background:var(--surface)}.camera-console-head{display:flex;justify-content:space-between;gap:12px;align-items:start}.camera-console h2{margin:5px 0 0;font:600 20px var(--font-body)}.health-chip{padding:7px 9px;border:1px solid var(--sage);color:var(--sage-text);border-radius:5px}.health-chip.degraded{border-color:var(--ember);color:var(--ember)}.health-chip.unknown{border-color:var(--ink-mute);color:var(--ink-mute)}.health-chip.degraded i,.health-chip.unknown i{background:var(--ink-mute);box-shadow:none;animation:none}.camera-stage{min-height:220px;margin:19px 0;border:1px solid var(--line);border-radius:var(--radius-card);background:var(--ground);display:grid;place-items:center;overflow:hidden}.camera-stage img{width:100%;height:100%;max-height:420px;object-fit:contain}.live-fallback{max-width:330px;padding:22px;text-align:center}.live-fallback span{display:block;margin-bottom:11px;color:var(--ink-mute);font-size:34px}.live-fallback strong{display:block}.live-fallback p{color:var(--ink-mute);font-size:12.5px;line-height:1.5}.camera-actions{display:flex;flex-wrap:wrap;gap:9px}.camera-actions button{min-height:44px;padding:10px 16px;border:1px solid var(--ember);border-radius:var(--radius-pill);color:var(--ink);background:var(--ember);font:600 13px var(--font-body);cursor:pointer}.camera-actions button:hover{background:var(--ember);border-color:var(--ember)}.camera-actions .quiet-action{color:var(--ink);border-color:var(--line);background:transparent}.camera-actions .quiet-action:hover{background:var(--surface-2);border-color:var(--ink-mute)}.live-session{color:var(--sage-text);font-size:12.5px}.camera-facts{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0 0}.camera-facts div{min-width:0;padding-top:11px;border-top:1px solid var(--line)}.camera-facts dt{color:var(--ink-mute);font:500 10px var(--font-mono);text-transform:uppercase;letter-spacing:.08em}.camera-facts dd{margin:5px 0 0;overflow-wrap:anywhere;color:var(--ink);font:12px var(--font-mono)}@keyframes beacon{50%{opacity:.55}}@media(max-width:850px){.camera-heading{display:block}.camera-beacon{display:inline-block;margin-top:16px}.camera-grid{grid-template-columns:1fr}.camera-console{padding:15px}.camera-facts{grid-template-columns:1fr 1fr}.camera-stage{min-height:190px}.camera-actions button{flex:1 1 160px}}@media(prefers-reduced-motion:reduce){.camera-beacon i,.health-chip i{animation:none}}
</style>
